/* prog30_escape_unescape.c
 * Reimplementation of the original binary's observable behaviour.
 *
 * Usage:
 *   prog30_escape_unescape escape   <string>
 *   prog30_escape_unescape unescape <string>
 *
 * The program prints the converted string followed by a newline.
 * Errors:
 *   USAGE          – not enough arguments
 *   INVALID_MODE   – mode is not "escape" nor "unescape"
 *   INVALID        – input longer than 1023 characters or malformed escape
 */

#include <stdio.h>
#include <string.h>

#define MAX_INPUT 1023

/* Escape: copy the input, turning special characters into C‑style
 * escape sequences.
 */
static void do_escape(const char *in)
{
    for (size_t i = 0; in[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)in[i];
        switch (c) {
            case '\\': fputs("\\\\", stdout); break;   /* backslash */
            case '"':  fputs("\\\"", stdout); break;   /* double quote */
            case '\n': fputs("\\n",  stdout); break;   /* newline */
            case '\t': fputs("\\t",  stdout); break;   /* tab */
            default:    putchar(c);           break;
        }
    }
    putchar('\n');
}

/* Unescape: interpret the four escape sequences used by the program.
 * Returns 1 on success, 0 on malformed input.
 */
static int do_unescape(const char *in)
{
    for (size_t i = 0; in[i] != '\0'; ++i) {
        if (in[i] != '\\') {
            putchar(in[i]);
            continue;
        }
        /* Backslash encountered – must have a following character */
        if (in[i + 1] == '\0') {
            return 0;               /* malformed */
        }
        switch (in[i + 1]) {
            case '\\': putchar('\\'); break;
            case '"':  putchar('"');  break;
            case 'n':   putchar('\n'); break;
            case 't':   putchar('\t'); break;
            default:    return 0;      /* unknown escape */
        }
        ++i;   /* skip the escaped character */
    }
    putchar('\n');
    return 1;
}

int main(int argc, char *argv[])
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *mode = argv[1];
    const char *data = argv[2];

    if (strlen(data) > MAX_INPUT) {
        puts("INVALID");
        return 0;
    }

    if (strcmp(mode, "escape") == 0) {
        do_escape(data);
        return 0;
    }

    if (strcmp(mode, "unescape") == 0) {
        if (!do_unescape(data)) {
            puts("INVALID");
        }
        return 0;
    }

    puts("INVALID_MODE");
    return 0;
}
